INSERT INTO t_permission(id,create_by,create_time,permission_code,permission_name,permission_type,action_type,built_in,status,resource_type,scope_type,description) SELECT gen_random_uuid()::text,'SYSTEM',CURRENT_TIMESTAMP,x.code,x.name,'MENU_ACTION',x.action,true,1,'EDUCATION_SCORE','ROLE',x.description FROM (VALUES ('education:score:scheme:view','查看考核方案','VIEW','查看成绩考核方案'),('education:score:scheme:manage','管理考核方案','MANAGE','维护人工考核方案'),('education:score:scheme:publish','发布考核方案','PUBLISH','发布考核方案'),('education:score:gradebook:view','查看成绩册','VIEW','查看成绩册'),('education:score:gradebook:entry','录入成绩','ENTRY','录入人工成绩'),('education:score:gradebook:submit','提交成绩册','SUBMIT','提交成绩册审核'),('education:score:gradebook:review','审核成绩册','REVIEW','审核成绩册'),('education:score:gradebook:publish','发布成绩','PUBLISH','发布成绩册')) x(code,name,action,description) ON CONFLICT(permission_code) DO NOTHING;
INSERT INTO t_role_permission(role_id,permission_id) SELECT r.id,p.id FROM t_role r CROSS JOIN t_permission p WHERE r.role_code IN('ROLE_PLATFORM_ADMIN','SUPER_ADMIN','EDU_ADMIN') AND p.permission_code LIKE 'education:score:%' ON CONFLICT DO NOTHING;
INSERT INTO t_role_permission(role_id,permission_id) SELECT r.id,p.id FROM t_role r CROSS JOIN t_permission p WHERE r.role_code='EDU_TEACHER' AND p.permission_code IN('education:score:scheme:view','education:score:gradebook:view','education:score:gradebook:entry','education:score:gradebook:submit') ON CONFLICT DO NOTHING;
